"""Sector and objective pages (Solutions). One data entry per page, one shared layout."""


def scen(label, credits, brief, intro, prod, picks_intro, picks, choice, gen_text, res, publish, meta_intro, meta):
    steps = [{'u': brief}]
    if prod:
        steps.append({'a': intro, 'card': dict(t='prod', **prod)})
        steps.append({'a': picks_intro, 'card': {'t': 'picks', 'list': picks, 'pick': 0}})
    else:
        steps.append({'a': intro + ' ' + picks_intro, 'card': {'t': 'picks', 'list': picks, 'pick': 0}})
    steps += [{'u': choice}, {'a': gen_text, 'card': {'t': 'gen', 'cost': 300 if prod else 280}},
              {'a': 'Ta vidéo est prête :' if 'img' not in res else 'Voilà ta vidéo et le visuel :', 'card': dict(t='res', **res)},
              {'u': publish}, {'a': meta_intro, 'card': dict(t='meta', **meta)}]
    return {'label': label, 'credits': credits, 'steps': steps}


