def build_sector(b, slug, d):
    sec, head, stack = b.section, b.head, b.stack
    plain, grad = d['h']
    body = stack(
        b.hero_center(slug, ('Solutions', d['pill']), plain, grad, d['lede'], demo=b.chat_custom([d['scen']])),
        sec(stack(head('Les angles qui marchent', 'Des accroches pensées', 'pour votre secteur.',
                       "Des exemples d'angles que le chat vous propose, et pourquoi ils fonctionnent sur Meta."), b.hooks(d['hooks'])), cls='night'),
        sec(stack(head('Pourquoi Growthity', 'Moins de temps,', 'plus de résultats.'), b.pains(*d['pains']))),
        sec(stack(head('Ce que vous obtenez', 'Tout ce qu\'il faut', 'pour vendre sur Meta.'), b.features(d['bento'], md=d['md'])), cls='tint'),
        sec(stack(head('Pour qui', 'Toutes les activités', 'du secteur.'), b.uses([(u, None) for u in d['uses']]))),
        stack(b.section(b.faq2(d['faq'])),
              b.section(stack(head('À découvrir aussi', 'Allez plus loin', 'avec Growthity.'), b.related(d['rel'])), cls='tint', style='padding-top:60px'),
              b.final()))
    return (d['meta'][0], d['meta'][1], body)
